/// x86 instruction read/write information.
///
/// Port of `x86::InstInternal::query_rw_info()` (asmjit/x86/x86instapi.cpp)
/// and of the `OpRWInfo` / `InstRWInfo` structures (asmjit/core/inst.h).
/// The tables (`InstDB::rw_info_*`) are in x86_rw_info.g.dart, generated by
/// tool/gen_x86_rwinfo.dart from the upstream x86instdb.cpp tables.

import '../core/inst_api.dart';
import '../core/operand.dart';
import '../core/reg_type.dart';
import 'x86.dart';
import 'x86_emit.dart' show X86EmitOptions;
import 'x86_inst_db.g.dart';
import 'x86_opcode.dart';
import 'x86_operands.dart';
import 'x86_rw_info.g.dart';
import 'x86_simd.dart';

/// `InstDB::RWInfo`.
class X86RWInfo {
  static const int kCategoryGeneric = 0;
  static const int kCategoryGenericEx = 1;
  static const int kCategoryMov = 2;
  static const int kCategoryMovabs = 3;
  static const int kCategoryImul = 4;
  static const int kCategoryMovh64 = 5;
  static const int kCategoryPunpcklxx = 6;
  static const int kCategoryVmaskmov = 7;
  static const int kCategoryVmovddup = 8;
  static const int kCategoryVmovmskpd = 9;
  static const int kCategoryVmovmskps = 10;
  static const int kCategoryVmov1_2 = 11;
  static const int kCategoryVmov1_4 = 12;
  static const int kCategoryVmov1_8 = 13;
  static const int kCategoryVmov2_1 = 14;
  static const int kCategoryVmov4_1 = 15;
  static const int kCategoryVmov8_1 = 16;

  final int category;
  final int rmInfo;
  final List<int> opInfoIndex;

  const X86RWInfo(this.category, this.rmInfo, this.opInfoIndex);
}

/// `InstDB::RWInfoOp`.
class X86RWInfoOp {
  final int rByteMask;
  final int wByteMask;
  final int physId;
  final int consecutiveLeadCount;
  final int flags;

  const X86RWInfoOp(this.rByteMask, this.wByteMask, this.physId,
      this.consecutiveLeadCount, this.flags);
}

/// `InstDB::RWInfoRm`.
class X86RWInfoRm {
  static const int kCategoryNone = 0;
  static const int kCategoryFixed = 1;
  static const int kCategoryConsistent = 2;
  static const int kCategoryHalf = 3;
  static const int kCategoryQuarter = 4;
  static const int kCategoryEighth = 5;

  static const int kFlagAmbiguous = 0x01;
  static const int kFlagPextrw = 0x02;
  static const int kFlagMovssMovsd = 0x04;
  static const int kFlagFeatureIfRMI = 0x08;

  final int category;
  final int rmOpsMask;
  final int fixedSize;
  final int flags;

  /// Name of the `CpuFeatures::X86` feature (empty when none).
  final String rmFeature;

  const X86RWInfoRm(this.category, this.rmOpsMask, this.fixedSize, this.flags,
      this.rmFeature);
}

/// Instruction data of [instId] that upstream keeps in `InstInfo`,
/// `CommonInfo` and `AdditionalInfo` (control flow, same-register hint and
/// the `kMovOp` flag).
int x86InstControlFlow(int instId) => (kX86InstRwData[instId] >> 17) & 0x7;
int x86InstSameRegHint(int instId) => (kX86InstRwData[instId] >> 20) & 0x3;

int _lsbMask(int n) => n >= 64 ? -1 : (1 << n) - 1;

/// `Support::fill_trailing_bits()`.
int _fillTrailingBits(int x) {
  var v = x;
  v |= v >>> 1;
  v |= v >>> 2;
  v |= v >>> 4;
  v |= v >>> 8;
  v |= v >>> 16;
  v |= v >>> 32;
  return v;
}

/// `Operand_::x86_rm_size()`: the size in the operand signature, which is 0
/// for mask, tile, control and debug registers (`RegTraits`).
int _rmSize(Object op) => switch (op) {
      X86KReg() || X86Tmm() || X86CReg() || X86DReg() => 0,
      BaseReg r => r.size,
      BaseMem m => m.size,
      _ => 0,
    };

bool _isGp(Object op) => op is X86Gp;
bool _isVec(Object op) => op is X86Xmm || op is X86Ymm || op is X86Zmm;
bool _isMem(Object op) => op is BaseMem;
bool _isReg(Object op) => op is BaseReg;
bool _isImm(Object op) => op is Imm;

/// `Mem::is_offset_64bit()`: no base register (nor label).
bool _isOffset64Bit(BaseMem m) =>
    m is X86Mem && m.base == null && m.label == null;

void _zeroExtendGp(OpRWInfo op, X86Gp reg, int nativeGpSize) {
  if (reg.size + 4 == nativeGpSize) {
    op.addOpFlags(OpRWFlags.kZExt);
    op.extendByteMask = ~op.writeByteMask & 0xFF;
  }
}

void _zeroExtendAvxVec(OpRWInfo op) {
  final msk = ~_fillTrailingBits(op.writeByteMask);
  if (msk != 0) {
    op.addOpFlags(OpRWFlags.kZExt);
    op.extendByteMask = msk;
  }
}

void _zeroExtendNonVec(OpRWInfo op, BaseReg reg) {
  // `rw_reg_group_byte_mask_table`.
  final groupMask = switch (reg.type) {
    RegType.segment => 0x3,
    RegType.x86St => 0x3FF,
    RegType.x86Bnd => 0xFFFF,
    _ => reg.group == RegGroup.vec ? -1 : 0xFF,
  };
  final msk = ~_fillTrailingBits(op.writeByteMask) & groupMask;
  if (msk != 0) {
    op.addOpFlags(OpRWFlags.kZExt);
    op.extendByteMask = msk;
  }
}

void _handleAvx512(int instId, int options, BaseReg? extraReg, InstRWInfo out) {
  if (extraReg != null && extraReg.type == RegType.mask && out.opCount > 0) {
    // AVX-512 instruction that uses a destination with {k} register (zeroing
    // vs masking).
    out.extraReg.addOpFlags(OpRWFlags.kRead);
    out.extraReg.readByteMask = 0xFF;
    if ((options & X86EmitOptions.kX86_ZMask) == 0 &&
        (kX86InstDb[instId].avx512Flags & X86Avx512Flags.kImplicitZ) == 0) {
      out.operands[0].addOpFlags(OpRWFlags.kRead);
      out.operands[0].readByteMask |= out.operands[0].writeByteMask;
    }
  }
}

bool _hasSameRegType(List<Object> regs) {
  final t = (regs[0] as BaseReg).type;
  for (var i = 1; i < regs.length; i++) {
    if ((regs[i] as BaseReg).type != t) return false;
  }
  return true;
}

/// `InstInternal::query_rw_info()`: fills [out] with the read/write
/// information of instruction [instId] with [operands] (registers, memory
/// operands and immediates), [options] ([X86EmitOptions]) and the optional
/// [extraReg]. Returns false for an invalid instruction/operand combination
/// (`Error::kInvalidInstruction`).
bool x86QueryRWInfo(
    bool is64Bit, int instId, List<Object> operands, InstRWInfo out,
    {int options = 0, BaseReg? extraReg}) {
  if (instId < 0 || instId >= kX86InstRwData.length) return false;
  final opCount = operands.length;
  if (opCount > 6) return false;

  final data = kX86InstRwData[instId];
  final instRwInfo =
      opCount == 2 ? kX86RwInfoA[data & 0xFF] : kX86RwInfoB[(data >> 8) & 0xFF];
  final instRmInfo = kX86RwInfoRm[instRwInfo.rmInfo];

  out.instFlags = (data >> 16) & 1;
  out.opCount = opCount;
  out.rmFeature = instRmInfo.rmFeature;
  out.extraReg.clear();

  var opTypeMask = 0;
  final nativeGpSize = is64Bit ? 8 : 4;

  const r = OpRWFlags.kRead;
  const w = OpRWFlags.kWrite;
  const x = OpRWFlags.kRW;
  const regM = OpRWFlags.kRegMem;
  const regPhys = OpRWFlags.kRegPhysId;
  const mibRead = OpRWFlags.kMemBaseRead | OpRWFlags.kMemIndexRead;

  // Operand type bits as upstream `OperandType` (reg = 1, mem = 2, imm = 3).
  int opType(Object op) => _isReg(op)
      ? 1
      : _isMem(op)
          ? 2
          : _isImm(op)
              ? 3
              : 4;

  if (instRwInfo.category <= X86RWInfo.kCategoryGenericEx) {
    var rmOpsMask = 0;
    var rmMaxSize = 0;

    for (var i = 0; i < opCount; i++) {
      final op = out.operands[i];
      final srcOp = operands[i];
      final rwOpData = kX86RwInfoOp[instRwInfo.opInfoIndex[i]];

      opTypeMask |= 1 << opType(srcOp);

      if (!_isReg(srcOp) && !_isMem(srcOp)) {
        op.clear();
        continue;
      }

      op.opFlags = rwOpData.flags & ~OpRWFlags.kZExt;
      op.physId = rwOpData.physId;
      op.rmSize = 0;

      var rByteMask = rwOpData.rByteMask;
      var wByteMask = rwOpData.wByteMask;

      if (op.isRead && rByteMask == 0) rByteMask = _lsbMask(_rmSize(srcOp));
      if (op.isWrite && wByteMask == 0) wByteMask = _lsbMask(_rmSize(srcOp));

      op.readByteMask = rByteMask;
      op.writeByteMask = wByteMask;
      op.extendByteMask = 0;
      op.consecutiveLeadCount = rwOpData.consecutiveLeadCount;

      if (srcOp is BaseReg) {
        // Zero extension.
        if (op.isWrite) {
          if (srcOp is X86Gp) {
            // GP registers on X64 are special:
            //   - 8-bit and 16-bit writes aren't zero extended.
            //   - 32-bit writes ARE zero extended.
            _zeroExtendGp(op, srcOp, nativeGpSize);
          } else if ((rwOpData.flags & OpRWFlags.kZExt) != 0) {
            // Otherwise follow ZExt.
            _zeroExtendNonVec(op, srcOp);
          }
        }

        // Aggregate values required to calculate valid Reg/M info.
        final size = _rmSize(srcOp);
        if (size > rmMaxSize) rmMaxSize = size;
        rmOpsMask |= 1 << i;
      } else {
        final memOp = srcOp as BaseMem;
        // The RW flags of BASE+INDEX are either provided by the data, which
        // means that the instruction is border-case, or they are deduced from
        // the operand.
        if (memOp.base != null && !op.hasOpFlag(OpRWFlags.kMemBaseRW)) {
          op.addOpFlags(OpRWFlags.kMemBaseRead);
        }
        if (memOp.index != null && !op.hasOpFlag(OpRWFlags.kMemIndexRW)) {
          op.addOpFlags(OpRWFlags.kMemIndexRead);
        }
      }
    }

    // Only keep kMovOp if the instruction is actually register to register
    // move of the same kind.
    if (out.hasInstFlag(InstRWFlags.kMovOp)) {
      if (!(opCount >= 2 &&
          opTypeMask == (1 << 1) &&
          _hasSameRegType(operands))) {
        out.instFlags &= ~InstRWFlags.kMovOp;
      }
    }

    // Special cases require more logic.
    if ((instRmInfo.flags &
            (X86RWInfoRm.kFlagMovssMovsd |
                X86RWInfoRm.kFlagPextrw |
                X86RWInfoRm.kFlagFeatureIfRMI)) !=
        0) {
      if ((instRmInfo.flags & X86RWInfoRm.kFlagMovssMovsd) != 0) {
        if (opCount == 2) {
          if (_isReg(operands[0]) && _isReg(operands[1])) {
            // Doesn't zero extend the destination.
            out.operands[0].extendByteMask = 0;
          }
        }
      } else if ((instRmInfo.flags & X86RWInfoRm.kFlagPextrw) != 0) {
        if (opCount == 3 && operands[1] is X86Mm) {
          out.rmFeature = '';
          rmOpsMask = 0;
        }
      } else if ((instRmInfo.flags & X86RWInfoRm.kFlagFeatureIfRMI) != 0) {
        if (opCount != 3 || !_isImm(operands[2])) {
          out.rmFeature = '';
        }
      }
    }

    rmOpsMask &= instRmInfo.rmOpsMask;
    if (rmOpsMask != 0 && (options & X86EmitOptions.kX86_ER) == 0) {
      for (var i = 0; i < 6; i++) {
        if ((rmOpsMask & (1 << i)) == 0) continue;
        final op = out.operands[i];
        op.addOpFlags(regM);

        switch (instRmInfo.category) {
          case X86RWInfoRm.kCategoryFixed:
            op.rmSize = instRmInfo.fixedSize;
          case X86RWInfoRm.kCategoryConsistent:
            op.rmSize = _rmSize(operands[i]);
          case X86RWInfoRm.kCategoryHalf:
            op.rmSize = rmMaxSize ~/ 2;
          case X86RWInfoRm.kCategoryQuarter:
            op.rmSize = rmMaxSize ~/ 4;
          case X86RWInfoRm.kCategoryEighth:
            op.rmSize = rmMaxSize ~/ 8;
        }
      }
    }

    // Special cases per instruction.
    if (instRwInfo.category == X86RWInfo.kCategoryGenericEx) {
      if (instId == X86InstId.kVpternlogd || instId == X86InstId.kVpternlogq) {
        if (opCount == 4 && operands[3] is Imm) {
          final predicate = (operands[3] as Imm).value & 0xFF;
          if ((predicate >> 4) == (predicate & 0xF)) {
            out.operands[0].clearOpFlags(OpRWFlags.kRead);
            out.operands[0].readByteMask = 0;
          }
        }
      }
    }

    _handleAvx512(instId, options, extraReg, out);
    return true;
  }

  final o = out.operands;
  switch (instRwInfo.category) {
    case X86RWInfo.kCategoryMov:
      // Special case for 'mov' instruction. Here there are some variants that
      // we have to handle as 'mov' can be used to move between GP, segment,
      // control and debug registers. Moving between GP registers also allow
      // to use memory operand.

      // We will again set the flag if it's actually a move from GP to GP
      // register, otherwise this flag cannot be set.
      out.instFlags &= ~InstRWFlags.kMovOp;

      if (opCount == 2) {
        final op0 = operands[0];
        final op1 = operands[1];
        if (op0 is BaseReg && op1 is BaseReg) {
          if (op0 is X86Gp && op1 is X86Gp) {
            o[0].reset(w | regM, op0.size);
            o[1].reset(r | regM, op1.size);
            _zeroExtendGp(o[0], op0, nativeGpSize);
            out.instFlags |= InstRWFlags.kMovOp;
            return true;
          }

          if (op0 is X86Gp && op1 is X86SReg) {
            o[0].reset(w | regM, nativeGpSize);
            o[0].rmSize = 2;
            o[1].reset(r, 2);
            return true;
          }

          if (op0 is X86SReg && op1 is X86Gp) {
            o[0].reset(w, 2);
            o[1].reset(r | regM, 2);
            o[1].rmSize = 2;
            return true;
          }

          if (op0 is X86Gp && (op1 is X86CReg || op1 is X86DReg)) {
            o[0].reset(w, nativeGpSize);
            o[1].reset(r, nativeGpSize);
            return true;
          }

          if ((op0 is X86CReg || op0 is X86DReg) && op1 is X86Gp) {
            o[0].reset(w, nativeGpSize);
            o[1].reset(r, nativeGpSize);
            return true;
          }
        }

        if (op0 is BaseReg && op1 is BaseMem) {
          if (op0 is X86Gp) {
            if (!_isOffset64Bit(op1)) {
              o[0].reset(w, op0.size);
            } else {
              o[0].reset(w | regPhys, op0.size, X86RegId.rax.index);
            }
            o[1].reset(r | mibRead, op0.size);
            _zeroExtendGp(o[0], op0, nativeGpSize);
            return true;
          }

          if (op0 is X86SReg) {
            o[0].reset(w, 2);
            o[1].reset(r, 2);
            return true;
          }
        }

        if (op0 is BaseMem && op1 is BaseReg) {
          if (op1 is X86Gp) {
            o[0].reset(w | mibRead, op1.size);
            if (!_isOffset64Bit(op0)) {
              o[1].reset(r, op1.size);
            } else {
              o[1].reset(r | regPhys, op1.size, X86RegId.rax.index);
            }
            return true;
          }

          if (op1 is X86SReg) {
            o[0].reset(w | mibRead, 2);
            o[1].reset(r, 2);
            return true;
          }
        }

        if (op0 is X86Gp && op1 is Imm) {
          o[0].reset(w | regM, op0.size);
          o[1].clear();
          _zeroExtendGp(o[0], op0, nativeGpSize);
          return true;
        }

        if (op0 is BaseMem && op1 is Imm) {
          // Upstream reads the size of the memory operand here.
          o[0].reset(w | mibRead, op0.size);
          o[1].clear();
          return true;
        }
      }

    case X86RWInfo.kCategoryMovabs:
      if (opCount == 2) {
        final op0 = operands[0];
        final op1 = operands[1];
        if (op0 is X86Gp && op1 is BaseMem) {
          o[0].reset(w | regPhys, op0.size, X86RegId.rax.index);
          o[1].reset(r | mibRead, op0.size);
          _zeroExtendGp(o[0], op0, nativeGpSize);
          return true;
        }

        if (op0 is BaseMem && op1 is X86Gp) {
          o[0].reset(w | mibRead, op1.size);
          o[1].reset(r | regPhys, op1.size, X86RegId.rax.index);
          return true;
        }

        if (op0 is X86Gp && op1 is Imm) {
          o[0].reset(w, op0.size);
          o[1].clear();
          _zeroExtendGp(o[0], op0, nativeGpSize);
          return true;
        }
      }

    case X86RWInfo.kCategoryImul:
      // Special case for 'imul' instruction.
      //
      // There are 3 variants in general:
      //
      //   1. Standard multiplication: 'A = A * B'.
      //   2. Multiplication with imm: 'A = B * C'.
      //   3. Extended multiplication: 'A:B = B * C'.
      if (opCount == 2) {
        final op0 = operands[0];
        final op1 = operands[1];
        if (op0 is BaseReg && op1 is Imm) {
          o[0].reset(x, op0.size);
          o[1].clear();
          if (op0 is X86Gp) _zeroExtendGp(o[0], op0, nativeGpSize);
          return true;
        }

        if (op0 is X86Gp && op0.size == 2 && _rmSize(op1) == 1) {
          // imul ax, r8/m8 <- AX = AL * r8/m8
          o[0].reset(x | regPhys, 2, X86RegId.rax.index);
          o[0].readByteMask = _lsbMask(1);
          o[1].reset(r | regM, 1);
        } else {
          // imul r?, r?/m?
          final size = (op0 as BaseReg).size;
          o[0].reset(x, size);
          o[1].reset(r | regM, size);
          if (op0 is X86Gp) _zeroExtendGp(o[0], op0, nativeGpSize);
        }

        if (op1 is BaseMem) o[1].addOpFlags(mibRead);
        return true;
      }

      if (opCount == 3) {
        if (operands[2] is Imm) {
          o[0].reset(w, _rmSize(operands[0]));
          o[1].reset(r | regM, _rmSize(operands[1]));
          o[2].clear();

          final op0 = operands[0];
          if (op0 is X86Gp) _zeroExtendGp(o[0], op0, nativeGpSize);
          if (operands[1] is BaseMem) o[1].addOpFlags(mibRead);
          return true;
        } else {
          o[0].reset(w | regPhys, _rmSize(operands[0]), X86RegId.rdx.index);
          o[1].reset(x | regPhys, _rmSize(operands[1]), X86RegId.rax.index);
          o[2].reset(r | regM, _rmSize(operands[2]));

          final op0 = operands[0];
          final op1 = operands[1];
          if (op0 is X86Gp) _zeroExtendGp(o[0], op0, nativeGpSize);
          if (op1 is X86Gp) _zeroExtendGp(o[1], op1, nativeGpSize);
          if (operands[2] is BaseMem) o[2].addOpFlags(mibRead);
          return true;
        }
      }

    case X86RWInfo.kCategoryMovh64:
      // Special case for 'movhpd|movhps' instructions. Note that this is only
      // required for legacy (non-AVX) variants as AVX instructions use either
      // 2 or 3 operands that are in `kCategoryGeneric` category.
      if (opCount == 2) {
        if (_isVec(operands[0]) && _isMem(operands[1])) {
          o[0].reset(w, 8);
          o[0].writeByteMask = _lsbMask(8) << 8;
          o[1].reset(r | mibRead, 8);
          return true;
        }

        if (_isMem(operands[0]) && _isVec(operands[1])) {
          o[0].reset(w | mibRead, 8);
          o[1].reset(r, 8);
          o[1].readByteMask = _lsbMask(8) << 8;
          return true;
        }
      }

    case X86RWInfo.kCategoryPunpcklxx:
      // Special case for 'punpcklbw|punpckldq|punpcklwd' instructions.
      if (opCount == 2) {
        if (operands[0] is X86Xmm) {
          o[0].reset(x, 16);
          o[0].readByteMask = 0x0F0F;
          o[0].writeByteMask = 0xFFFF;
          o[1].reset(r, 16);
          o[1].writeByteMask = 0x0F0F;

          if (operands[1] is X86Xmm) return true;

          if (_isMem(operands[1])) {
            o[1].addOpFlags(mibRead);
            return true;
          }
        }

        if (operands[0] is X86Mm) {
          o[0].reset(x, 8);
          o[0].readByteMask = 0x0F;
          o[0].writeByteMask = 0xFF;
          o[1].reset(r, 4);
          o[1].readByteMask = 0x0F;

          if (operands[1] is X86Mm) return true;

          if (_isMem(operands[1])) {
            o[1].addOpFlags(mibRead);
            return true;
          }
        }
      }

    case X86RWInfo.kCategoryVmaskmov:
      // Special case for 'vmaskmovpd|vmaskmovps|vpmaskmovd|vpmaskmovq'
      // instructions.
      if (opCount == 3) {
        if (_isVec(operands[0]) && _isVec(operands[1]) && _isMem(operands[2])) {
          o[0].reset(w, _rmSize(operands[0]));
          o[1].reset(r, _rmSize(operands[1]));
          o[2].reset(r | mibRead, _rmSize(operands[1]));

          _zeroExtendAvxVec(o[0]);
          return true;
        }

        if (_isMem(operands[0]) && _isVec(operands[1]) && _isVec(operands[2])) {
          o[0].reset(x | mibRead, _rmSize(operands[1]));
          o[1].reset(r, _rmSize(operands[1]));
          o[2].reset(r, _rmSize(operands[2]));
          return true;
        }
      }

    case X86RWInfo.kCategoryVmovddup:
      // Special case for 'vmovddup' instruction. This instruction has an
      // interesting semantic as 128-bit XMM version only uses 64-bit memory
      // operand (m64), however, 256/512-bit versions use 256/512-bit memory
      // operand, respectively.
      if (opCount == 2) {
        if (_isVec(operands[0]) && _isVec(operands[1])) {
          final o0Size = _rmSize(operands[0]);
          final o1Size = o0Size == 16 ? 8 : o0Size;

          o[0].reset(w, o0Size);
          o[1].reset(r | regM, o1Size);
          o[1].readByteMask &= 0x00FF00FF00FF00FF;

          _zeroExtendAvxVec(o[0]);
          _handleAvx512(instId, options, extraReg, out);
          return true;
        }

        if (_isVec(operands[0]) && _isMem(operands[1])) {
          final o0Size = _rmSize(operands[0]);
          final o1Size = o0Size == 16 ? 8 : o0Size;

          o[0].reset(w, o0Size);
          o[1].reset(r | mibRead, o1Size);

          _zeroExtendAvxVec(o[0]);
          _handleAvx512(instId, options, extraReg, out);
          return true;
        }
      }

    case X86RWInfo.kCategoryVmovmskpd:
    case X86RWInfo.kCategoryVmovmskps:
      // Special case for 'vmovmskpd|vmovmskps' instructions.
      if (opCount == 2) {
        if (_isGp(operands[0]) && _isVec(operands[1])) {
          o[0].reset(w, 1);
          o[0].extendByteMask = _lsbMask(nativeGpSize - 1) << 1;
          o[1].reset(r, _rmSize(operands[1]));
          return true;
        }
      }

    case X86RWInfo.kCategoryVmov1_2:
    case X86RWInfo.kCategoryVmov1_4:
    case X86RWInfo.kCategoryVmov1_8:
      // Special case for instructions where the destination is 1:N
      // (narrowing).
      final shift = instRwInfo.category - X86RWInfo.kCategoryVmov1_2 + 1;

      if (opCount >= 2) {
        if (opCount >= 3) {
          if (opCount > 3) return false;
          o[2].clear();
        }

        if (_isReg(operands[0]) && _isReg(operands[1])) {
          final size1 = _rmSize(operands[1]);
          final size0 = size1 >> shift;

          o[0].reset(w, size0);
          o[1].reset(r, size1);

          if ((instRmInfo.rmOpsMask & 0x1) != 0) {
            o[0].addOpFlags(regM);
            o[0].rmSize = size0;
          }

          if ((instRmInfo.rmOpsMask & 0x2) != 0) {
            o[1].addOpFlags(regM);
            o[1].rmSize = size1;
          }

          // Handle 'pmovmskb|vpmovmskb'.
          final op0 = operands[0];
          if (op0 is X86Gp) _zeroExtendGp(o[0], op0, nativeGpSize);

          if (_isVec(op0)) _zeroExtendAvxVec(o[0]);

          _handleAvx512(instId, options, extraReg, out);
          return true;
        }

        if (_isReg(operands[0]) && _isMem(operands[1])) {
          final s = _rmSize(operands[1]);
          final size1 = s != 0 ? s : 16;
          final size0 = size1 >> shift;

          o[0].reset(w, size0);
          o[1].reset(r | mibRead, size1);

          if (_isVec(operands[0])) _zeroExtendAvxVec(o[0]);

          return true;
        }

        if (_isMem(operands[0]) && _isReg(operands[1])) {
          final size1 = _rmSize(operands[1]);
          final size0 = size1 >> shift;

          o[0].reset(w | mibRead, size0);
          o[1].reset(r, size1);

          _handleAvx512(instId, options, extraReg, out);
          return true;
        }
      }

    case X86RWInfo.kCategoryVmov2_1:
    case X86RWInfo.kCategoryVmov4_1:
    case X86RWInfo.kCategoryVmov8_1:
      // Special case for instructions where the destination is N:1
      // (widening).
      final shift = instRwInfo.category - X86RWInfo.kCategoryVmov2_1 + 1;

      if (opCount >= 2) {
        if (opCount >= 3) {
          if (opCount > 3) return false;
          o[2].clear();
        }

        final size0 = _rmSize(operands[0]);
        final size1 = size0 >> shift;

        o[0].reset(w, size0);
        o[1].reset(r, size1);

        if (_isVec(operands[0])) _zeroExtendAvxVec(o[0]);

        if (_isReg(operands[0]) && _isReg(operands[1])) {
          if ((instRmInfo.rmOpsMask & 0x1) != 0) {
            o[0].addOpFlags(regM);
            o[0].rmSize = size0;
          }

          if ((instRmInfo.rmOpsMask & 0x2) != 0) {
            o[1].addOpFlags(regM);
            o[1].rmSize = size1;
          }

          _handleAvx512(instId, options, extraReg, out);
          return true;
        }

        if (_isReg(operands[0]) && _isMem(operands[1])) {
          o[1].addOpFlags(mibRead);
          _handleAvx512(instId, options, extraReg, out);
          return true;
        }
      }
  }

  return false;
}
